// Aperture masks and pupil textures (STUDIO-TOOLS §1 and §6, phase A6).
//
//   node tools/assets/aperture-masks.mjs            writes public/assets/aperture/*.png and index.json
//   node tools/assets/aperture-masks.mjs --check    regenerates in memory and compares with what is on disk
//
// Every file is 512 x 512, 8-bit grey, and is drawn from a recipe (kind, parameters, seed) by pure code: nothing
// is generated by an image model and nothing is copied (project rule: clean room). The index lists each file's
// recipe, seed and two hashes: `sha256` of the PNG as written and `pixelsSha256` of the raw pixels. The pixel
// hash is the canonical one (the bytes of a compressed stream can differ between builds of zlib).
//
// Convention (also in index.json): the image covers [-1, 1]^2 with v up, the unit circle is inscribed, and the
// grey level is the transmission of the pupil at that point (255 open, 0 blocked). Shapes keep their vertices on
// the unit circle (circumradius 1). Textures are drawn inside the unit disc and are 0 outside it; the engine
// multiplies them with the shape of the stop.

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { clamp01, coverage, cos, encodePng, PI, rng, sha256, sin, smoothstep, toByte, TWO_PI, valueNoise } from './common.mjs';

export const GENERATOR = { name: 'aperture-masks', version: 1 };
export const SIZE = 512;
/** Pixel size in the normalised coordinates. */
const PX = 2 / SIZE;

const pad = (n) => String(n).padStart(2, '0');

/** Every mask of the set, in the order of the index. `recipe` is all that the pixels depend on besides `seed`. */
export function recipes() {
  const list = [];
  for (let n = 3; n <= 18; n++) list.push({ id: `polygon_${pad(n)}`, file: `polygon-${pad(n)}.png`, group: 'polygon', seed: 0, recipe: { kind: 'polygon', blades: n, roundness: 0, rotationDeg: 0 }, description: `${n} straight blades` });
  for (let n = 3; n <= 18; n++) list.push({ id: `polygon_${pad(n)}_curved`, file: `polygon-${pad(n)}-curved.png`, group: 'polygon', seed: 0, recipe: { kind: 'polygon', blades: n, roundness: 0.5, rotationDeg: 0 }, description: `${n} curved blades, roundness 0.5` });
  for (const [n, ratio] of [[4, 0.38], [5, 0.42], [6, 0.5], [8, 0.6]]) list.push({ id: `star_${n}`, file: `star-${n}.png`, group: 'star', seed: 0, recipe: { kind: 'star', points: n, innerRatio: ratio, rotationDeg: 0 }, description: `${n}-point star` });
  list.push({ id: 'heart', file: 'heart.png', group: 'heart', seed: 0, recipe: { kind: 'heart', samples: 160, fitRadius: 0.96 }, description: 'heart' });
  list.push({ id: 'holes_7', file: 'holes-7.png', group: 'holes', seed: 0, recipe: { kind: 'holes', count: 7, pitch: 0.6, holeRadius: 0.27, rotationDeg: 0 }, description: '7 holes (centre and a ring of 6)' });
  list.push({ id: 'holes_19', file: 'holes-19.png', group: 'holes', seed: 0, recipe: { kind: 'holes', count: 19, pitch: 0.36, holeRadius: 0.15, rotationDeg: 0 }, description: '19 holes (hexagonal packing)' });
  list.push({ id: 'annulus_30', file: 'annulus-30.png', group: 'annulus', seed: 0, recipe: { kind: 'annulus', obstruction: 0.3 }, description: 'ring with a central obstruction of 0.3' });
  list.push({ id: 'annulus_50', file: 'annulus-50.png', group: 'annulus', seed: 0, recipe: { kind: 'annulus', obstruction: 0.5 }, description: 'ring with a central obstruction of 0.5' });
  list.push({ id: 'onion_rings', file: 'onion-rings.png', group: 'texture', seed: 1003, recipe: { kind: 'onionRings', period: 0.09, jitter: 0.45 }, description: 'concentric ring modulation of a pupil (unit amplitude: the engine scales it)' });
  list.push({ id: 'dust', file: 'dust.png', group: 'texture', seed: 1001, recipe: { kind: 'dust', specks: 150, fibres: 7, smudges: 5 }, description: 'dust specks, fibres and haze on a lens' });
  list.push({ id: 'scratches', file: 'scratches.png', group: 'texture', seed: 1002, recipe: { kind: 'scratches', lines: 38, arcs: 9 }, description: 'fine scratches and arcs' });
  list.push({ id: 'filter_mesh', file: 'filter-mesh.png', group: 'texture', seed: 0, recipe: { kind: 'mesh', period: 0.0625, width: 0.012, depth: 0.6 }, description: 'fine diamond mesh of a diffusion filter' });
  return list;
}

// ---------------------------------------------------------------------------
// Signed distances (negative inside)
// ---------------------------------------------------------------------------

/** Distance to a segment. */
function segDist(px, py, ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  const t = clamp01(((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy));
  const qx = ax + t * dx - px;
  const qy = ay + t * dy - py;
  return Math.sqrt(qx * qx + qy * qy);
}

/** Signed distance to a closed polygon given as [x0, y0, x1, y1, ...] (even-odd inside test, exact distance). */
function polygonSd(points) {
  const n = points.length / 2;
  return (x, y) => {
    let d2 = Infinity;
    let inside = false;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const ax = points[2 * j];
      const ay = points[2 * j + 1];
      const bx = points[2 * i];
      const by = points[2 * i + 1];
      const d = segDist(x, y, ax, ay, bx, by);
      if (d * d < d2) d2 = d * d;
      if (ay > y !== by > y && x < ((bx - ax) * (y - ay)) / (by - ay) + ax) inside = !inside;
    }
    const d = Math.sqrt(d2);
    return inside ? -d : d;
  };
}

const rad = (deg) => (deg * PI) / 180;

function polygonShape({ blades, roundness, rotationDeg }) {
  // First vertex straight up, then counter-clockwise; the edge normals sit halfway between vertices.
  const apothem = cos(PI / blades);
  const normals = [];
  for (let k = 0; k < blades; k++) {
    const a = PI / 2 + rad(rotationDeg) + (TWO_PI * k) / blades + PI / blades;
    normals.push([cos(a), sin(a)]);
  }
  if (roundness <= 0) {
    return (x, y) => {
      let m = -Infinity;
      for (const [nx, ny] of normals) {
        const s = nx * x + ny * y - apothem;
        if (s > m) m = s;
      }
      return m;
    };
  }
  // Rounded blades: each edge is an arc of radius apothem / roundness, tangent to the straight edge at its middle;
  // roundness 1 is the inscribed circle, 0 the straight polygon. The opening is the intersection of the discs.
  const radius = apothem / roundness;
  const centres = normals.map(([nx, ny]) => [(apothem - radius) * nx, (apothem - radius) * ny]);
  return (x, y) => {
    let m = -Infinity;
    for (const [cx, cy] of centres) {
      const s = Math.sqrt((x - cx) * (x - cx) + (y - cy) * (y - cy)) - radius;
      if (s > m) m = s;
    }
    return m;
  };
}

function starShape({ points, innerRatio, rotationDeg }) {
  const pts = [];
  for (let k = 0; k < 2 * points; k++) {
    const a = PI / 2 + rad(rotationDeg) + (PI * k) / points;
    const r = k % 2 === 0 ? 1 : innerRatio;
    pts.push(r * cos(a), r * sin(a));
  }
  return polygonSd(pts);
}

function heartShape({ samples, fitRadius }) {
  // The classic parametric heart; centred on its bounding box and scaled so that its farthest point sits at fitRadius.
  const raw = [];
  for (let k = 0; k < samples; k++) {
    const t = (TWO_PI * k) / samples;
    const s = sin(t);
    raw.push(16 * s * s * s, 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
  }
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  for (let i = 0; i < raw.length; i += 2) {
    minX = Math.min(minX, raw[i]);
    maxX = Math.max(maxX, raw[i]);
    minY = Math.min(minY, raw[i + 1]);
    maxY = Math.max(maxY, raw[i + 1]);
  }
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  let far = 0;
  for (let i = 0; i < raw.length; i += 2) far = Math.max(far, Math.sqrt((raw[i] - cx) * (raw[i] - cx) + (raw[i + 1] - cy) * (raw[i + 1] - cy)));
  const k = fitRadius / far;
  const pts = raw.map((v, i) => (i % 2 === 0 ? (v - cx) * k : (v - cy) * k));
  return polygonSd(pts);
}

function holeCentres({ count, pitch, rotationDeg }) {
  const s = pitch;
  const rot = rad(rotationDeg) + PI / 2;
  const at = (r, a) => [r * cos(a + rot), r * sin(a + rot)];
  const list = [[0, 0]];
  for (let k = 0; k < 6; k++) list.push(at(s, (PI * k) / 3));
  if (count === 19) {
    const root3 = Math.sqrt(3);
    for (let k = 0; k < 6; k++) list.push(at(2 * s, (PI * k) / 3));
    for (let k = 0; k < 6; k++) list.push(at(root3 * s, (PI * k) / 3 + PI / 6));
  }
  return list;
}

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------

const centre = (i) => (i + 0.5) / (SIZE / 2) - 1;

/** Fills a float image by calling `f(x, y)` (transmission, 0..1) at every pixel centre; v is up. */
function paint(f) {
  const img = new Float64Array(SIZE * SIZE);
  for (let py = 0; py < SIZE; py++) {
    const y = -centre(py);
    for (let px = 0; px < SIZE; px++) img[py * SIZE + px] = f(centre(px), y);
  }
  return img;
}

const discCover = (x, y) => coverage(Math.sqrt(x * x + y * y) - 1, PX);

/** Applies `fn(index, x, y)` to every pixel of the bounding box of a disc (centre cx, cy, radius r) inside the image. */
function eachInBox(cx, cy, r, fn) {
  const x0 = Math.max(0, Math.floor((cx - r + 1) * (SIZE / 2)));
  const x1 = Math.min(SIZE - 1, Math.ceil((cx + r + 1) * (SIZE / 2)));
  const y0 = Math.max(0, Math.floor((1 - (cy + r)) * (SIZE / 2)));
  const y1 = Math.min(SIZE - 1, Math.ceil((1 - (cy - r)) * (SIZE / 2)));
  for (let py = y0; py <= y1; py++) for (let px = x0; px <= x1; px++) fn(py * SIZE + px, centre(px), -centre(py));
}

function dustImage(seed, { specks, fibres, smudges }) {
  const rand = rng(seed);
  const t = new Float64Array(SIZE * SIZE).fill(1);
  const darken = (i, alpha) => {
    t[i] *= 1 - alpha;
  };
  // Broad haze: a few large, very soft blobs.
  for (let k = 0; k < smudges; k++) {
    const a = rand() * TWO_PI;
    const rr = Math.sqrt(rand()) * 0.9;
    const cx = rr * cos(a);
    const cy = rr * sin(a);
    const r = 0.25 + rand() * 0.25;
    const alpha = 0.06 + rand() * 0.08;
    eachInBox(cx, cy, r, (i, x, y) => darken(i, alpha * (1 - smoothstep(0, r, Math.sqrt((x - cx) * (x - cx) + (y - cy) * (y - cy))))));
  }
  // Specks: soft ellipses of random size, from fine to coarse (log-uniform radius).
  for (let k = 0; k < specks; k++) {
    const a = rand() * TWO_PI;
    const rr = Math.sqrt(rand()) * 0.97;
    const cx = rr * cos(a);
    const cy = rr * sin(a);
    const r = 0.004 * (1 + rand() * rand() * 7);
    const squash = 1 + rand() * 0.8;
    const ang = rand() * PI;
    const ca = cos(ang);
    const sa = sin(ang);
    const alpha = 0.25 + rand() * 0.65;
    eachInBox(cx, cy, r * squash * 1.6, (i, x, y) => {
      const dx = x - cx;
      const dy = y - cy;
      const u = (dx * ca + dy * sa) / squash;
      const w = -dx * sa + dy * ca;
      const d = Math.sqrt(u * u + w * w);
      darken(i, alpha * coverage(d - r, PX * 1.2));
    });
  }
  // Fibres: short curved hairs, a polyline of small steps with a bend.
  for (let k = 0; k < fibres; k++) {
    const a = rand() * TWO_PI;
    const rr = Math.sqrt(rand()) * 0.8;
    let x = rr * cos(a);
    let y = rr * sin(a);
    let dir = rand() * TWO_PI;
    const bend = (rand() - 0.5) * 0.25;
    const steps = 14 + Math.floor(rand() * 14);
    const width = 0.0035 + rand() * 0.003;
    const alpha = 0.35 + rand() * 0.4;
    for (let s = 0; s < steps; s++) {
      const nx = x + 0.018 * cos(dir);
      const ny = y + 0.018 * sin(dir);
      eachInBox((x + nx) / 2, (y + ny) / 2, 0.03, (i, px, py) => darken(i, alpha * coverage(segDist(px, py, x, y, nx, ny) - width, PX)));
      x = nx;
      y = ny;
      dir += bend;
    }
  }
  const out = new Float64Array(SIZE * SIZE);
  for (let py = 0; py < SIZE; py++) for (let px = 0; px < SIZE; px++) out[py * SIZE + px] = t[py * SIZE + px] * discCover(centre(px), -centre(py));
  return out;
}

function scratchesImage(seed, { lines, arcs }) {
  const rand = rng(seed);
  const t = new Float64Array(SIZE * SIZE).fill(1);
  for (let k = 0; k < lines; k++) {
    const a = rand() * TWO_PI;
    const rr = Math.sqrt(rand()) * 1.0;
    const x0 = rr * cos(a);
    const y0 = rr * sin(a);
    const dir = rand() * PI;
    const len = 0.25 + rand() * 1.2;
    const x1 = x0 + len * cos(dir);
    const y1 = y0 + len * sin(dir);
    const width = 0.0022 + rand() * 0.004;
    const alpha = 0.3 + rand() * 0.55;
    eachInBox((x0 + x1) / 2, (y0 + y1) / 2, len / 2 + 0.02, (i, x, y) => {
      t[i] *= 1 - alpha * coverage(segDist(x, y, x0, y0, x1, y1) - width, PX);
    });
  }
  for (let k = 0; k < arcs; k++) {
    // An arc of a large circle (a cleaning scratch): centre far away, radius 0.6..2, a limited angular span.
    const a = rand() * TWO_PI;
    const R = 0.6 + rand() * 1.4;
    const ca = cos(a);
    const sa = sin(a);
    const off = rand() * 0.9;
    // The circle passes at distance `off` from the origin along direction a.
    const cx = (off - R) * ca;
    const cy = (off - R) * sa;
    const half = 0.18 + rand() * 0.25; // half-span as cos threshold of the angle seen from the centre
    const cosHalf = cos(half);
    const width = 0.0025 + rand() * 0.003;
    const alpha = 0.3 + rand() * 0.5;
    for (let py = 0; py < SIZE; py++) {
      for (let px = 0; px < SIZE; px++) {
        const x = centre(px);
        const y = -centre(py);
        const dx = x - cx;
        const dy = y - cy;
        const d = Math.sqrt(dx * dx + dy * dy);
        if (Math.abs(d - R) > 0.02) continue;
        if ((dx * ca + dy * sa) / d < cosHalf) continue;
        t[py * SIZE + px] *= 1 - alpha * coverage(Math.abs(d - R) - width, PX);
      }
    }
  }
  const out = new Float64Array(SIZE * SIZE);
  for (let py = 0; py < SIZE; py++) for (let px = 0; px < SIZE; px++) out[py * SIZE + px] = t[py * SIZE + px] * discCover(centre(px), -centre(py));
  return out;
}

/** The float image (0..1) of one mask. */
export function renderFloat(recipe, seed) {
  switch (recipe.kind) {
    case 'polygon': {
      const sd = polygonShape(recipe);
      return paint((x, y) => coverage(sd(x, y), PX));
    }
    case 'star': {
      const sd = starShape(recipe);
      return paint((x, y) => coverage(sd(x, y), PX));
    }
    case 'heart': {
      const sd = heartShape(recipe);
      return paint((x, y) => coverage(sd(x, y), PX));
    }
    case 'holes': {
      const centres = holeCentres(recipe);
      return paint((x, y) => {
        let m = Infinity;
        for (const [cx, cy] of centres) {
          const d = Math.sqrt((x - cx) * (x - cx) + (y - cy) * (y - cy)) - recipe.holeRadius;
          if (d < m) m = d;
        }
        return coverage(m, PX);
      });
    }
    case 'annulus':
      return paint((x, y) => {
        const r = Math.sqrt(x * x + y * y);
        return coverage(Math.max(r - 1, recipe.obstruction - r), PX);
      });
    case 'onionRings':
      // 0.5 + 0.5 sin(2 pi r / period + phase(r)): the phase wanders a little with a smooth noise so that the rings
      // are not a perfect grating, as turned grooves are not.
      return paint((x, y) => {
        const r = Math.sqrt(x * x + y * y);
        const phase = recipe.jitter * 6.283185307179586 * (valueNoise(r * 9, 0.5, seed) - 0.5);
        return (0.5 + 0.5 * sin((TWO_PI * r) / recipe.period + phase)) * discCover(x, y);
      });
    case 'dust':
      return dustImage(seed, recipe);
    case 'scratches':
      return scratchesImage(seed, recipe);
    case 'mesh': {
      // A diamond mesh: the lines run at 45 degrees (u = (x + y) / sqrt 2, w = (x - y) / sqrt 2).
      const k = Math.sqrt(0.5);
      const line = (s) => {
        const f = s / recipe.period;
        return coverage(Math.abs(f - Math.floor(f + 0.5)) * recipe.period - recipe.width / 2, PX);
      };
      return paint((x, y) => {
        const a = line((x + y) * k);
        const b = line((x - y) * k);
        const lines = 1 - (1 - a) * (1 - b);
        return (1 - recipe.depth * lines) * discCover(x, y);
      });
    }
    default:
      throw new Error(`unknown mask kind ${recipe.kind}`);
  }
}

/** The 8-bit grey pixels of one mask (row-major, top row first). */
export function renderMask(recipe, seed) {
  const f = renderFloat(recipe, seed);
  const out = new Uint8Array(SIZE * SIZE);
  for (let i = 0; i < out.length; i++) out[i] = toByte(f[i]);
  return out;
}

// ---------------------------------------------------------------------------
// The set
// ---------------------------------------------------------------------------

/**
 * Renders everything in memory: `{ index, files }` with `files` mapping a file name to its PNG bytes. Pure: the
 * command line below is the only part that touches the disk.
 */
export function buildAll(only) {
  const files = {};
  const masks = [];
  for (const entry of recipes()) {
    if (only && !only.includes(entry.id)) continue;
    const pixels = renderMask(entry.recipe, entry.seed);
    const png = encodePng(pixels, SIZE, SIZE);
    files[entry.file] = png;
    masks.push({ ...entry, size: SIZE, bytes: png.length, sha256: sha256(png), pixelsSha256: sha256(pixels) });
  }
  const index = {
    generator: `tools/assets/${GENERATOR.name}.mjs`,
    version: GENERATOR.version,
    size: SIZE,
    bitDepth: 8,
    convention:
      'Covers [-1, 1]^2, v up, unit circle inscribed; grey = transmission of the pupil (255 open); shapes have circumradius 1; textures are 0 outside the unit disc. sha256 is of the PNG file; pixelsSha256 of the raw 8-bit pixels (canonical).',
    masks,
  };
  return { index, files };
}

// ---------------------------------------------------------------------------
// Command line
// ---------------------------------------------------------------------------

const DEFAULT_OUT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'public', 'assets', 'aperture');

function main(argv) {
  const check = argv.includes('--check');
  const outArg = argv.indexOf('--out');
  const out = outArg >= 0 ? argv[outArg + 1] : DEFAULT_OUT;
  const { index, files } = buildAll();
  if (check) {
    const onDisk = JSON.parse(readFileSync(join(out, 'index.json'), 'utf8'));
    let bad = 0;
    for (const m of index.masks) {
      const disk = onDisk.masks.find((x) => x.id === m.id);
      if (!disk || disk.pixelsSha256 !== m.pixelsSha256) {
        console.error(`DIFFERENT ${m.id}`);
        bad++;
      }
    }
    console.log(bad === 0 ? `ok: ${index.masks.length} masks reproduce their pixel hashes` : `${bad} masks differ`);
    process.exitCode = bad === 0 ? 0 : 1;
    return;
  }
  mkdirSync(out, { recursive: true });
  for (const [name, bytes] of Object.entries(files)) writeFileSync(join(out, name), bytes);
  writeFileSync(join(out, 'index.json'), JSON.stringify(index, null, 2) + '\n');
  const total = index.masks.reduce((n, m) => n + m.bytes, 0);
  console.log(`wrote ${index.masks.length} masks to ${out} (${(total / 1024).toFixed(0)} KiB)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main(process.argv.slice(2));
